MAP
    NAME "SS_MAP_TRAT_MEDIDORES_TRATADA"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_agua_tratada_medidor_sector.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_TRAT_MEDIDORES"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "gm_agua_tratada_sector from l_agua_tratada_medidores_sector using unique id_agua_tratada_medidor_sector using srid=32614"
        TYPE POINT
        LABELITEM "nb_agua_tratada_medidores_sectores"
        CLASS
            NAME "Sector Agua tratada medidor"
            STYLE
                SYMBOL "puntos"
                SIZE 8
                COLOR 170 000 255	
                OUTLINECOLOR 170 000 255	
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 19
                COLOR 170 000 255
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP